import{z as s,x as p,o as t,c as B,q as r,j as o,D as e,d as l,s as E,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"干涉光刻","description":"","frontmatter":{"title":"干涉光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/interference-lithography.md","filePath":"litho/interference-lithography.md","lastUpdated":1791063341000}'),d={name:"litho/interference-lithography.md"};function h(A,a,m,c,_,D){const i=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="干涉光刻" tabindex="-1">干涉光刻 <a class="header-anchor" href="#干涉光刻" aria-label="Permalink to &quot;干涉光刻&quot;">​</a></h1><div class="epigraph"><p>两束相干光的干涉条纹给出极密的周期线，不需要透镜把掩模成像；代价是几乎只能做周期，没有任意逻辑。</p><footer>—— 对照 interference lithography（Lloyd 镜、achromatic IL）在实验室与模板中的传统</footer></div><p><a href="/litho/multibeam-direct-write">上一课</a>说明串行直写的墙。缺口是并行光子的非投影用法。本课钉干涉光刻。X 射线与近场，留给<a href="/litho/xray-near-field">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两束平面波干涉，周期 \\(λ/(2\\sinθ)\\)，可在胶上得到大面积光栅。无需投影物镜，NA 概念换成交角。应用：实验室纳米光栅、某些自对准模板、研究用 periodic test。不能直接印 SRAM 二维任意孔，除非多次曝光叠加或与切线组合——那就又回到分解复杂度。</p><p><span class="marginnote">代个数感受周期公式：\\(\\lambda=193\\) nm、两束各以 \\(\\theta=60°\\) 入射，周期 \\(=193/(2\\times0.866)\\approx 111\\) nm，即约 56 nm 半节距——不用任何镜头就进半百纳米。交角越大周期越短，\\(\\theta\\to90°\\) 时极限是 \\(\\lambda/2\\)。</span></p><p>缺口是<strong>周期特化</strong>，不是新波长扫描机。把干涉当 EUV 替代，丢了逻辑图形的信息容量。</p>',7)),(t(),o(n,null,{default:e(()=>[E(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%90%8C%E4%B8%80%E6%BF%80%E5%85%89%22%5D%20--%3E%20PR%5B%22%E6%8A%95%E5%BD%B1%E5%85%89%E5%88%BB%22%5D%0A%20%20SRC%20--%3E%20IL%5B%22%E5%B9%B2%E6%B6%89%E5%85%89%E5%88%BB%22%5D%0A%20%20PR%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E6%90%BA%E5%B8%A6%E4%BB%BB%E6%84%8F%202D%20%E4%BF%A1%E6%81%AF%22%5D%0A%20%20MASK%20--%3E%20LOGIC%5B%22%E9%80%BB%E8%BE%91%20%2F%20SRAM%20%E5%8F%AF%E5%8D%B0%22%5D%0A%20%20IL%20--%3E%20BS%5B%22%E5%88%86%E6%9D%9F%E9%95%9C%E6%8B%86%E6%88%90%E4%B8%A4%E6%9D%9F%E5%B9%B3%E9%9D%A2%E6%B3%A2%22%5D%0A%20%20BS%20--%3E%20FR%5B%22%E6%9D%A1%E7%BA%B9%E5%91%A8%E6%9C%9F%20%CE%BB%2F(2sin%CE%B8)%22%5D%0A%20%20FR%20--%3E%20GR%5B%22%E5%8F%AA%E8%83%BD%E5%8D%B0%E5%91%A8%E6%9C%9F%E5%85%89%E6%A0%85%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>这张图回答的问题是：同样都靠「两束光加强一个周期」，为什么投影光刻能印逻辑、干涉光刻不能——分岔点在信息由谁携带：掩模，还是条纹本身。</p><h3 id="与离轴照明的关系" tabindex="-1">与离轴照明的关系 <a class="header-anchor" href="#与离轴照明的关系" aria-label="Permalink to &quot;与离轴照明的关系&quot;">​</a></h3><p>投影光刻的偶极是「在瞳里选两束」去加强某一周期；干涉光刻是直接两束、没有掩模频谱。主干 OAI 课已讲前者。本课不重推部分相干。</p><p><span class="marginnote">Achromatic IL 用宽带减相干长度问题，适合大面积，仍是周期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验室：激光分束、交角、稳定。工业：罕见作为逻辑主曝光；可能作为辅助光栅。与 SAQP：有人讨论干涉做 mandrel，仍要切线。评估用「能否任意 2D」一票否决逻辑全流程。</p><p><span class="marginnote">「相干」就是两束光的波峰波谷长期对得上表：激光的波列足够长，两束分开再相遇时能形成位置固定的明暗条纹；手电一类的宽谱光源波列太短，条纹刚摆好就被自己洗掉了。干涉光刻的一切稳定性要求，本质都是保住这本「对表」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强度 \\(I \\propto 1+\\cos(Kx)\\)，K 由交角定。对比度靠相干与剂量。焦深可以很大（准直束），这是优点。信息量：一维周期的自由度远小于掩模场。</p><p><span class="marginnote">常见误区：以为「不用透镜 = 更简单更便宜」。干涉光刻省掉的那颗镜头，换来的是只能印一维周期的硬约束——逻辑芯片要的是任意二维图形，两者的信息容量差着数量级。省设备不等于省复杂度，复杂度只是搬到了图形分解里。</span></p>',10)),(t(),o(n,null,{default:e(()=>[E(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TWO%5B%22%E4%B8%A4%E6%9D%9F%E7%9B%B8%E5%B9%B2%E5%85%89%22%5D%20--%3E%20GR%5B%22%E5%91%A8%E6%9C%9F%E5%85%89%E6%A0%85%22%5D%0A%20%20GR%20--%3E%20USE%5B%22%E6%A8%A1%E6%9D%BF%20%2F%20%E7%A0%94%E7%A9%B6%22%5D%0A%20%20GR%20--%3E%20NO%5B%22%E9%9D%9E%E4%BB%BB%E6%84%8F%E9%80%BB%E8%BE%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 EUV 干涉源幻想成已量产扫描机。不给实验室最小周期当厂规。</p><p>后课默认：无掩模光子路可以印周期；下一课更短波长的 X 射线与近场为何没成为逻辑主路径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>干涉光刻用交角定周期，大面积、深焦深，图形几乎必须周期。</li><li>不能替代投影光刻的任意 2D 逻辑。</li><li>与偶极照明同族的是「两束」，不是同一台机器。</li><li>出处：interference lithography 实验室与模板传统。</li></ul>',5))])}const S=s(d,[["render",h]]);export{u as __pageData,S as default};
